/** Native browser tools. Web previews always use the protected Gecko runtime. */
final class BrowserFeatures {
 final MainActivity a;
 FrameLayout content; View home; boolean fullscreen;
 static final int IMPORT=7401,EXPORT=7402;
 BrowserFeatures(MainActivity activity){a=activity;}
 LinearLayout column(){LinearLayout v=new LinearLayout(a);v.setOrientation(LinearLayout.VERTICAL);v.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));return v;}
 TextView text(String s,int size){TextView t=new TextView(a);t.setText(s);t.setTextSize(size);t.setTextColor(a.ink());t.setPadding(0,a.dp(8),0,a.dp(8));return t;}
 void toast(String s){Toast.makeText(a,s,Toast.LENGTH_LONG).show();}
 void attach(){content=new FrameLayout(a);a.web=new GeckoView(a);a.web.setAutofillEnabled(true);a.web.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_YES);content.addView(a.web,new FrameLayout.LayoutParams(-1,-1));a.root.addView(content,new LinearLayout.LayoutParams(-1,0,1));}
 void homepage(){if(a.current()==null)return;MainActivity.Tab t=a.current();t.home=true;t.url="kosher:home";t.title="Home";t.state=null;t.pendingUrl=null;t.session.loadUri("about:blank");showHome();a.address.setText("");a.renderTabs();a.updateBookmark();a.save();}
 void showHome(){a.chrome.home();}

 void syncHome(){if(a.current()!=null&&a.current().home)showHome();else if(home!=null){content.removeView(home);home=null;}}
 JSONArray array(String key){try{return new JSONArray(a.prefs.getString(key,"[]"));}catch(Exception e){return new JSONArray();}}
 void bind(MainActivity.Tab t){
  if(BrowserEngine.extension==null)return;
  t.session.getWebExtensionController().setMessageDelegate(BrowserEngine.extension,new WebExtension.MessageDelegate(){@Override public void onConnect(WebExtension.Port p){if(!p.sender.isTopLevel())return;t.port=p;p.setDelegate(new WebExtension.PortDelegate(){@Override public void onDisconnect(WebExtension.Port p){if(t.port==p)t.port=null;}});}},"kosherPage");
 }
 void command(String op,int size){MainActivity.Tab t=a.current();if(t==null||t.home||t.port==null){toast("Wait for a web page to finish loading.");return;}JSONObject m=new JSONObject();try{m.put("op",op);m.put("size",size);t.port.postMessage(m);}catch(Exception e){toast("This page does not support reader mode.");}}
 void reader(){command("reader",0);}
 void font(){LinearLayout c=column();TextView value=text("Reader font size",18);c.addView(value);SeekBar slider=new SeekBar(a);slider.setMax(22);slider.setProgress(a.prefs.getInt("reader_font",19)-14);c.addView(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){value.setText("Reader font: "+(p+14));if(user){a.prefs.edit().putInt("reader_font",p+14).apply();command("font",p+14);}}});new AlertDialog.Builder(a).setTitle("Reader font").setView(c).setPositiveButton("Done",null).show();}
 void find(){if(a.current()==null||a.current().home)return;GeckoSession session=a.current().session;LinearLayout c=column();EditText q=new EditText(a);q.setSingleLine();q.setHint("Find text on this page");q.setTextColor(a.ink());TextView result=text("",14);c.addView(q);c.addView(result);session.getFinder().setDisplayFlags(GeckoSession.FINDER_DISPLAY_HIGHLIGHT_ALL);Runnable next=()->session.getFinder().find(q.getText().toString(),GeckoSession.FINDER_FIND_FORWARD).accept(r->a.runOnUiThread(()->result.setText(r.found?r.current+" of "+r.total:"No matches")),e->a.runOnUiThread(()->result.setText("Search unavailable")));q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){next.run();}public void afterTextChanged(Editable e){}});AlertDialog d=new AlertDialog.Builder(a).setTitle("Find in page").setView(c).setPositiveButton("Next",null).setNeutralButton("Previous",null).setNegativeButton("Done",null).create();d.setOnShowListener(v->{d.getButton(-1).setOnClickListener(x->next.run());d.getButton(-3).setOnClickListener(x->session.getFinder().find(q.getText().toString(),GeckoSession.FINDER_FIND_BACKWARDS).accept(r->a.runOnUiThread(()->result.setText(r.found?r.current+" of "+r.total:"No matches"))));});d.setOnDismissListener(v->session.getFinder().clear());d.show();}
 void capture(MainActivity.Tab t){if(t==null||t.home||a.web.getSession()!=t.session)return;a.web.capturePixels().accept(bitmap->{if(bitmap==null)return;int w=240,h=Math.max(1,Math.min(480,bitmap.getHeight()*w/Math.max(1,bitmap.getWidth())));t.preview=Bitmap.createScaledBitmap(bitmap,w,h,true);},e->{});}
 JSONObject tabRecord(MainActivity.Tab t){JSONObject o=new JSONObject();try{o.put("url",t.url);o.put("title",t.title);o.put("desktop",t.desktop);if(t.state!=null)o.put("state",t.state);}catch(Exception ignored){}return o;}
 void remember(MainActivity.Tab t){if(t.home)return;JSONArray next=new JSONArray();next.put(tabRecord(t));JSONArray old=array("closed_tabs");for(int i=0;i<Math.min(19,old.length());i++)next.put(old.opt(i));a.prefs.edit().putString("closed_tabs",next.toString()).apply();}
 void tabs(){a.chrome.tabs();}

 void restoreRecord(JSONObject o,boolean select){if(o==null)return;String url=o.optString("url","kosher:home");if(!url.equals("kosher:home")&&!http(url))return;int previous=a.tabs.size();a.add(url,select,o.optBoolean("desktop",false));if(a.tabs.size()==previous)return;MainActivity.Tab t=a.tabs.get(a.tabs.size()-1);t.title=o.optString("title",t.title);String state=o.optString("state");if(!t.home&&!state.isEmpty())try{t.state=state;t.session.restoreState(GeckoSession.SessionState.fromString(state));}catch(Exception ignored){}a.renderTabs();}
 void closed(){JSONArray items=array("closed_tabs");String[] names=new String[items.length()];for(int i=0;i<names.length;i++)names[i]=items.optJSONObject(i).optString("title")+"\n"+items.optJSONObject(i).optString("url");new AlertDialog.Builder(a).setTitle("Recently closed").setItems(names,(d,w)->{restoreRecord(items.optJSONObject(w),true);JSONArray next=new JSONArray();for(int i=0;i<items.length();i++)if(i!=w)next.put(items.opt(i));a.prefs.edit().putString("closed_tabs",next.toString()).apply();}).setNegativeButton("Done",null).show();}
 void crash(MainActivity.Tab t){t.back=false;t.forward=false;if(a.current()!=t)return;new AlertDialog.Builder(a).setTitle("Tab stopped").setMessage("Your tabs were saved. Reload this page to recover it.").setPositiveButton("Reload",(d,w)->{String url=t.url,state=t.state;int index=a.tabs.indexOf(t);a.web.releaseSession();t.session.close();a.tabs.remove(t);a.add(url,true);MainActivity.Tab fresh=a.current();if(state!=null)try{fresh.session.restoreState(GeckoSession.SessionState.fromString(state));}catch(Exception ignored){}a.save();}).setNegativeButton("Later",null).show();}
 void toggleFullscreen(){fullscreen=!fullscreen;applyFullscreen();}
 void applyFullscreen(){a.updateBackHandling();a.chrome.fullscreen(fullscreen);a.getWindow().getDecorView().setSystemUiVisibility(fullscreen?View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY:0);if(!fullscreen)a.applyColors();if(fullscreen)toast("Press Back to leave full screen.");}

 void clearSite(){if(!a.pageAvailable())return;String host=Uri.parse(a.current().url).getHost();new AlertDialog.Builder(a).setTitle("Clear data for "+host).setMessage("This signs you out of this site and may affect its subdomains.").setPositiveButton("Cookies only",(d,w)->clear(host,StorageController.ClearFlags.COOKIES)).setNeutralButton("All site data",(d,w)->clear(host,StorageController.ClearFlags.SITE_DATA|StorageController.ClearFlags.AUTH_SESSIONS|StorageController.ClearFlags.PERMISSIONS)).setNegativeButton("Cancel",null).show();}
 void clear(String host,long flags){MainActivity.runtime.getStorageController().clearDataFromHost(host,flags).accept(v->toast("Site data cleared"),e->toast("Could not clear site data"));}
 void defaultBrowser(){try{if(Build.VERSION.SDK_INT>=29){RoleManager r=a.getSystemService(RoleManager.class);if(r.isRoleAvailable(RoleManager.ROLE_BROWSER)&&!r.isRoleHeld(RoleManager.ROLE_BROWSER)){a.startActivityForResult(r.createRequestRoleIntent(RoleManager.ROLE_BROWSER),7410);return;}}a.startActivity(new Intent(Settings.ACTION_MANAGE_DEFAULT_APPS_SETTINGS));}catch(Exception e){toast("Choose Kosher Browsing in Android default app settings.");}}
 void autofill(){try{if(Build.VERSION.SDK_INT>=35)a.startActivity(new Intent(Settings.ACTION_CREDENTIAL_PROVIDER));else{toast("In Android Settings, choose your password manager under Autofill service.");a.startActivity(new Intent(Settings.ACTION_SETTINGS));}}catch(Exception e){toast("Select your password manager in Android Settings → Autofill.");}}
 void dashboard(){JSONObject s;try{s=new JSONObject(a.prefs.getString("protection_stats","{}"));}catch(Exception e){s=new JSONObject();}new AlertDialog.Builder(a).setTitle("Protection dashboard").setMessage("Ad requests blocked: "+s.optLong("ads")+"\nRestricted site/search requests: "+s.optLong("sites")+"\nShorts requests blocked: "+s.optLong("shorts")+"\nNetwork images filtered: "+s.optLong("filteredImages")+"\nImages blocked on filter failure: "+s.optLong("failedImages")+"\n\nAlways active: adult domain/search rules, social blocks, strict Safe Search on supported search engines, image filtering, ad rules and Shorts blocking.\n\nCounts measure requests since this version was installed, including repeats. Inline images are filtered separately. Rule lists are bundled snapshots. Skin-color detection is heuristic; video/canvas and unknown sites are not fully covered.").setPositiveButton("Done",null).show();}
 void link(GeckoSession.ContentDelegate.ContextElement e){String url=e.linkUri;if(!http(url))return;new AlertDialog.Builder(a).setTitle(e.linkText==null?"Link":e.linkText).setMessage(url).setItems(new String[]{"Preview link","Open here","Open in new tab","Copy link","Share link","Bookmark link"},(d,w)->{switch(w){case 0:preview(url);break;case 1:a.navigate(url);break;case 2:a.add(url,true);break;case 3:((android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Link",url));toast("Link copied");break;case 4:share(url);break;case 5:saveBookmark(url,e.linkText==null?url:e.linkText,"");break;}}).setNegativeButton("Cancel",null).show();}
 void share(String url){try{a.startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,url),"Share link"));}catch(Exception e){toast("No sharing app available");}}
 void preview(String url){LinearLayout c=column();c.addView(text(url,14));GeckoView view=new GeckoView(a);MainActivity.Tab t=a.createTab(url);t.session.setContentDelegate(new GeckoSession.ContentDelegate(){@Override public void onExternalResponse(GeckoSession s,WebResponse r){try{if(r.body!=null)r.body.close();}catch(Exception ignored){}}});t.session.setNavigationDelegate(new GeckoSession.NavigationDelegate(){@Override public GeckoResult<AllowOrDeny> onLoadRequest(GeckoSession s,LoadRequest r){return GeckoResult.fromValue(http(r.uri)||r.uri.startsWith("moz-extension:")?AllowOrDeny.ALLOW:AllowOrDeny.DENY);}@Override public GeckoResult<GeckoSession> onNewSession(GeckoSession s,String uri){return GeckoResult.fromValue(null);}});t.session.open(MainActivity.runtime);view.setSession(t.session);c.addView(view,new LinearLayout.LayoutParams(-1,a.dp(340)));AlertDialog d=new AlertDialog.Builder(a).setTitle("Protected preview").setView(c).setPositiveButton("Open in new tab",(x,w)->a.add(url,true)).setNegativeButton("Close",null).create();d.setOnDismissListener(x->{view.releaseSession();t.session.close();});d.show();t.session.loadUri(url);}
 static boolean http(String url){return url!=null&&url.matches("(?i)^https?://[^\\s]+")&&Uri.parse(url).getHost()!=null;}
 void saveBookmark(String url,String title,String folder){if(!http(url)){toast("Only web pages can be bookmarked.");return;}JSONArray b=a.bookmarks();int i=a.bookmarkIndex(b,url);JSONObject o=i>=0?b.optJSONObject(i):new JSONObject();try{o.put("url",url);o.put("title",title.isEmpty()?url:title);o.put("folder",folder.trim());if(i<0)b.put(o);a.prefs.edit().putString("bookmarks",b.toString()).apply();a.updateBookmark();toast("Bookmark saved");}catch(Exception ignored){}}
 void editBookmark(JSONObject o){LinearLayout c=column();EditText title=new EditText(a),folder=new EditText(a);title.setTextColor(a.ink());folder.setTextColor(a.ink());title.setText(o.optString("title"));folder.setText(o.optString("folder"));title.setHint("Title");folder.setHint("Folder (blank = Unfiled)");title.setSingleLine();folder.setSingleLine();c.addView(title);c.addView(folder);new AlertDialog.Builder(a).setTitle("Edit bookmark").setView(c).setPositiveButton("Save",(d,w)->{saveBookmark(o.optString("url"),title.getText().toString(),folder.getText().toString());bookmarks();}).setNeutralButton("Delete",(d,w)->{a.removeBookmark(o.optString("url"));bookmarks();}).setNegativeButton("Cancel",null).show();}
 void bookmarks(){LinearLayout c=column();EditText search=new EditText(a);search.setTextColor(a.ink());search.setHint("Search titles, URLs and folders");search.setSingleLine();c.addView(search);Spinner folders=new Spinner(a);ArrayList<String> names=new ArrayList<>();names.add("All folders");names.add("Unfiled");JSONArray saved=a.bookmarks();for(int i=0;i<saved.length();i++){String f=saved.optJSONObject(i).optString("folder");if(!f.isEmpty()&&!names.contains(f))names.add(f);}folders.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,names));c.addView(folders);ListView list=new ListView(a);c.addView(list,new LinearLayout.LayoutParams(-1,a.dp(340)));ArrayList<JSONObject> visible=new ArrayList<>();Runnable refresh=()->{visible.clear();ArrayList<String> labels=new ArrayList<>();String q=search.getText().toString().toLowerCase(Locale.ROOT);int fi=folders.getSelectedItemPosition();for(int i=0;i<saved.length();i++){JSONObject o=saved.optJSONObject(i);String f=o.optString("folder"),label=o.optString("title")+"\n"+o.optString("url")+"\n"+(f.isEmpty()?"Unfiled":f);if((fi<=0||(fi==1?f.isEmpty():names.get(fi).equals(f)))&&label.toLowerCase(Locale.ROOT).contains(q)){visible.add(o);labels.add(label);}}list.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_list_item_1,labels));};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int n,int after){}public void onTextChanged(CharSequence s,int st,int before,int n){refresh.run();}public void afterTextChanged(Editable e){}});folders.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){refresh.run();}public void onNothingSelected(AdapterView<?> p){}});AlertDialog d=new AlertDialog.Builder(a).setTitle("Bookmarks · hold to edit").setView(c).setPositiveButton("Export",(x,w)->exportBookmarks()).setNeutralButton("Import",(x,w)->importBookmarks()).setNegativeButton("Done",null).create();list.setOnItemClickListener((p,v,pos,id)->{d.dismiss();a.navigate(visible.get(pos).optString("url"));});list.setOnItemLongClickListener((p,v,pos,id)->{d.dismiss();editBookmark(visible.get(pos));return true;});refresh.run();d.show();}
 void importBookmarks(){try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),IMPORT);}catch(Exception e){toast("No document picker available");}}
 void exportBookmarks(){try{a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").putExtra(Intent.EXTRA_TITLE,"Kosher-Browsing-bookmarks.json").addCategory(Intent.CATEGORY_OPENABLE),EXPORT);}catch(Exception e){toast("No document picker available");}}
 boolean result(int req,int code,Intent data){if(req!=IMPORT&&req!=EXPORT)return false;if(code!=Activity.RESULT_OK||data==null||data.getData()==null)return true;Uri uri=data.getData();if(req==EXPORT){String payload=a.bookmarks().toString();new Thread(()->{try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(payload.getBytes("UTF-8"));a.runOnUiThread(()->toast("Bookmarks exported"));}catch(Exception e){a.runOnUiThread(()->toast("Export failed"));}},"bookmark-export").start();}else new Thread(()->{try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>2*1024*1024)throw new IOException("Too large");}JSONArray incoming=new JSONArray(out.toString("UTF-8"));if(incoming.length()>10000)throw new IOException("Too many bookmarks");JSONArray checked=new JSONArray();for(int i=0;i<incoming.length();i++){JSONObject item=incoming.optJSONObject(i);if(item==null||!http(item.optString("url")))continue;JSONObject o=new JSONObject();o.put("url",item.optString("url"));o.put("title",item.optString("title",item.optString("url")));o.put("folder",item.optString("folder"));checked.put(o);}a.runOnUiThread(()->new AlertDialog.Builder(a).setTitle("Import "+checked.length()+" bookmarks?").setMessage("These will be merged with your existing bookmarks. Duplicate URLs are skipped.").setPositiveButton("Import",(d,w)->{JSONArray saved=a.bookmarks();int added=0;for(int i=0;i<checked.length();i++){JSONObject o=checked.optJSONObject(i);if(a.bookmarkIndex(saved,o.optString("url"))<0){saved.put(o);added++;}}a.prefs.edit().putString("bookmarks",saved.toString()).apply();a.updateBookmark();toast(added+" bookmarks imported");}).setNegativeButton("Cancel",null).show());}catch(Exception e){a.runOnUiThread(()->toast("Import failed. Choose a Kosher Browsing JSON bookmark export (up to 2 MB)."));}},"bookmark-import").start();return true;}
 void menu(){a.chrome.menu();}
}
